import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.dGCgOE9J.js";const s="/Qonnectra-docs/pr-27/images/manual/teil-b/qgis_projects.jpg",a="/Qonnectra-docs/pr-27/images/manual/teil-b/qgis_project_messages.jpg",d="/Qonnectra-docs/pr-27/images/manual/teil-b/qgis_project_form.jpg",l="/Qonnectra-docs/pr-27/images/manual/teil-b/qgis_wms_source.jpg",f=JSON.parse('{"title":"27. QGIS-Server und Kartendienste","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.md","filePath":"manual/teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.md"}'),o={name:"manual/teil-b-betrieb-admin-qgis/27-qgis-server-und-kartendienste.md"};function u(h,e,c,g,m,b){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_27-qgis-server-und-kartendienste" tabindex="-1">27. QGIS-Server und Kartendienste <a class="header-anchor" href="#_27-qgis-server-und-kartendienste" aria-label="Permalink to &quot;27. QGIS-Server und Kartendienste&quot;">​</a></h1><p>Zu Qonnectra gehört ein <strong>QGIS-Server</strong>. Er veröffentlicht die Netzdaten als standardisierte Kartendienste, die jedes GIS lesen kann – QGIS am Arbeitsplatz, das GIS einer Kommune, ein Planungsbüro. Was er zeigt, legt ein <strong>QGIS-Projekt</strong> fest, das Sie im Administrationsbereich hinterlegen. Umgekehrt binden Sie dort <strong>externe Kartendienste</strong> ein, die in der Karte der Weboberfläche als zusätzliche Layer erscheinen.</p><h2 id="_27-1-qgis-projekte-in-qonnectra-hinterlegen" tabindex="-1">27.1 QGIS-Projekte in Qonnectra hinterlegen <a class="header-anchor" href="#_27-1-qgis-projekte-in-qonnectra-hinterlegen" aria-label="Permalink to &quot;27.1 QGIS-Projekte in Qonnectra hinterlegen&quot;">​</a></h2><p>QGIS-Projekte stehen im Administrationsbereich unter „Api“ → „QGIS Projekte“.</p><p><img src="'+s+'" alt="Screenshot der Liste der QGIS-Projekte mit Anzeigename, Name, Erstellungsdatum und Konto im Inhaltsbereich" data-zoomable="true"></p><p>Ein Projekt legen Sie mit „QGIS Projekt hinzufügen“ an:</p><ul><li>„Projekt“ – trotz der Beschriftung der technische Name, der in den Adressen der Dienste erscheint. Nur Kleinbuchstaben, Ziffern, Binde- und Unterstriche, etwa <code>netzdokumentation</code>.</li><li>„Anzeigename“ – der Name in der Liste – und eine „Beschreibung“.</li><li>„QGIS Projektdatei“ – die Datei aus QGIS, <code>.qgs</code> oder <code>.qgz</code>.</li><li>Unter „Feature-Dateien“ – trotz der Beschriftung Datendateien, die das Projekt neben der Datenbank braucht, etwa ein Plan als <code>.dxf</code> oder ein Gebiet als <code>.geojson</code>.</li></ul><p>Das Projekt erstellen Sie in QGIS am Arbeitsplatz, mit Layern aus der Datenbank von Qonnectra, siehe Kapitel <a href="./25-qgis-arbeitsplatz-einrichten.html">QGIS-Arbeitsplatz einrichten</a>. Layer aus der Datenbank müssen dafür schon vor dem Hochladen den PostgreSQL-Dienst <code>qonnectra</code> verwenden, siehe Abschnitt <a href="./25-qgis-arbeitsplatz-einrichten.html#_25-2-verbindung-zur-postgis-datenbank-und-zu-den-diensten">Verbindung zur PostGIS-Datenbank</a>. Qonnectra lässt sie beim Hochladen unverändert, und eine Verbindung über Host, Benutzername und Passwort, wie sie am Arbeitsplatz über das VPN eingerichtet ist, erreicht der Server nicht. Umgestellt werden nur Layer, die auf GeoPackage-Dateien verweisen – sie zeigen danach über den Dienst auf die gleichnamige Tabelle der Datenbank –, und Layer aus hochgeladenen Datendateien, die danach auf deren Ablage auf dem Server zeigen. Anschließend prüft es das Projekt und meldet das Ergebnis über dem Formular.</p><p><img src="'+a+'" alt="Screenshot des Formulars eines QGIS-Projekts mit Hervorhebung der Meldungen nach dem Hochladen oben" data-zoomable="true"></p><p>Die Meldungen:</p><ul><li>„QGIS Projekt erfolgreich gespeichert. Bitte starten Sie den QGIS Server manuell mit docker-compose neu.“ – erscheint bei jedem Speichern. Ein Neustart ist nicht nötig: Der Server liest ein neues wie ein geändertes Projekt beim nächsten Abruf.</li><li>„GetCapabilities response does not look like a valid WMS document …“ – erscheint in der ausgelieferten Fassung bei jedem Hochladen, weil die Prüfung den Server unter einer falschen Adresse abfragt. Sie sagt nichts über das Projekt.</li><li>Meldungen zu fehlenden Datenquellen, ungültigen GeoPackage-Dateien oder einer neueren QGIS-Version – diese sind ernst zu nehmen. Das Projekt ist trotzdem gespeichert.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Projekt ist mit dem Speichern veröffentlicht, auch wenn die Prüfung Fehler meldet. Testen Sie die Dienste nach dem Hochladen in QGIS, bevor Sie die Adresse weitergeben.</p></div><p>Die Aktion „Mit PostgreSQL-Datenquellen herunterladen“ liefert ein hinterlegtes Projekt so zurück, wie der Server es verwendet, zum Öffnen am Arbeitsplatz. Dafür braucht der Arbeitsplatz den PostgreSQL-Dienst <code>qonnectra</code>, siehe Abschnitt <a href="./25-qgis-arbeitsplatz-einrichten.html#_25-2-verbindung-zur-postgis-datenbank-und-zu-den-diensten">Verbindung zur PostGIS-Datenbank</a>.</p><h2 id="_27-2-angebotene-dienste-wms-wfs-wmts-ogc-api-features" tabindex="-1">27.2 Angebotene Dienste: WMS, WFS, WMTS, OGC API Features <a class="header-anchor" href="#_27-2-angebotene-dienste-wms-wfs-wmts-ogc-api-features" aria-label="Permalink to &quot;27.2 Angebotene Dienste: WMS, WFS, WMTS, OGC API Features&quot;">​</a></h2><p>Der QGIS-Server bietet jedes hinterlegte Projekt über diese Dienste an:</p><ul><li><strong>WMS</strong> – Kartenbilder, zum Anzeigen.</li><li><strong>WFS</strong> – die Objekte selbst mit ihren Attributen, zum Abfragen und Weiterverarbeiten.</li><li><strong>WMTS</strong> – Kartenbilder in Kacheln, unter derselben Adresse wie der WMS mit <code>SERVICE=WMTS</code>, für die Layer und Gruppen, die in den Projekteigenschaften von QGIS unter „QGIS-Server“ → „WMTS“ freigegeben sind.</li><li><strong>OGC API Features</strong> – die Objekte als GeoJSON über eine REST-Schnittstelle.</li></ul><p>Die Adressen eines Projekts stehen in seinem Formular unter „Zugriffs-URLs“.</p><p><img src="'+d+'" alt="Screenshot des Formulars eines QGIS-Projekts mit Hervorhebung der Zugriffs-URLs für WMS, WFS und OGC API Features" data-zoomable="true"></p><p>„WMS-URL“ und „WFS-URL“ nennen nur den hinteren Teil der Adresse. Vollständig lauten sie mit der Adresse des QGIS-Servers davor, etwa:</p><p><code>https://qgis.ihre-domain.de/ows/?SERVICE=WMS&amp;MAP=/projects/netzdokumentation.qgs</code></p><p>„WFS3-URL (OGC API Features)“ ist ein Pfad auf der Adresse der Schnittstelle, etwa <code>https://api.ihre-domain.de/api/v1/wfs3/netzdokumentation/</code>.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Dienste liefern, was das QGIS-Projekt enthält, mit dessen Filtern und Stilen. Ein eigenes, reduziertes QGIS-Projekt für eine Stelle schränkt deren Zugriff jedoch nicht ein: Jedes aktive Konto kann über den Parameter <code>MAP</code> jedes hinterlegte Projekt abrufen, siehe Abschnitt <a href="#_27-3-authentifizierung-der-dienste">Authentifizierung der Dienste</a>.</p></div><h2 id="_27-3-authentifizierung-der-dienste" tabindex="-1">27.3 Authentifizierung der Dienste <a class="header-anchor" href="#_27-3-authentifizierung-der-dienste" aria-label="Permalink to &quot;27.3 Authentifizierung der Dienste&quot;">​</a></h2><p>Die Dienste verlangen eine Anmeldung mit Benutzername und Passwort eines Qonnectra-Kontos. In QGIS tragen Sie beide in der WMS- oder WFS-Verbindung unter „Authentifizierung“ als „Basic“ ein. Ohne Anmeldung antwortet der Server mit „401“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Dienste kennen keine Rollen. Jedes aktive Konto sieht jedes hinterlegte QGIS-Projekt mit allen Layern, auch ein Konto der Rolle „Viewer“ und eines ohne Gruppe. Was in keinem hinterlegten Projekt enthalten ist, liefern die Dienste nicht; einschränken lässt sich der Zugriff nur so, für alle Konten zugleich.</p></div><p>Für eine Stelle, die die Dienste dauerhaft abrufen soll, etwa das GIS einer Kommune, legen Sie ein eigenes Konto ohne Gruppe an. Es öffnet die Dienste, sieht aber in der Weboberfläche keine Daten, siehe Abschnitt <a href="./19-rollen-und-rechte.html#_19-1-benutzende-und-gruppen-anlegen">Benutzende und Gruppen anlegen</a>.</p><h2 id="_27-4-externe-wms-quellen-als-hintergrund-einbinden" tabindex="-1">27.4 Externe WMS-Quellen als Hintergrund einbinden <a class="header-anchor" href="#_27-4-externe-wms-quellen-als-hintergrund-einbinden" aria-label="Permalink to &quot;27.4 Externe WMS-Quellen als Hintergrund einbinden&quot;">​</a></h2><p>Externe Kartendienste – Luftbilder, Liegenschaftskarten, Bebauungspläne – binden Sie als <strong>WMS-Quelle</strong> ein. Ihre Layer erscheinen in der Legende der Karte als eigene Gruppe, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>. Die Quellen stehen unter „Api“ → „WMS-Layer“ – trotz der Beschriftung die Quellen, nicht die einzelnen Layer.</p><p>Eine Quelle gehört zu genau einem Projekt. Ihre Felder:</p><ul><li>„Projekt“ und „Name“ – der Name ist die Überschrift der Gruppe in der Legende.</li><li>„WMS-URL“ – die Adresse des Dienstes, mit festen Parametern wie <code>MAP</code> darin.</li><li>„Reihenfolge“ und „Aktiv“.</li><li>Unter „Authentifizierung“ „Benutzer“ und „Passwort“, falls der Dienst eine Anmeldung verlangt. Das Passwort wird verschlüsselt gespeichert.</li><li>Unter „PDF-Export“ die „Attribution“ – der Quellenvermerk, den die Lizenz des Dienstes verlangt. Ohne ihn erscheint der Dienst im PDF ohne Quellenvermerk.</li></ul><p>Beim Speichern einer neuen Quelle oder einer geänderten Adresse fragt Qonnectra die Layer des Dienstes ab und listet sie darunter auf. Je Layer legen Sie fest, ob er „Aktiviert“ ist, in welcher „Reihenfolge“ er steht, ab und bis zu welcher Zoomstufe er erscheint und wie deckend er ist – die Spalte „Transparenz“ meint die Deckkraft: 1 ist undurchsichtig.</p><p><img src="'+l+'" alt="Screenshot einer WMS-Quelle mit Hervorhebung der Felder oben und der abgefragten Layer darunter" data-zoomable="true"></p><p>Die Aktion „Empfohlene Einstellungen scannen und anwenden“ setzt die minimale Zoomstufe jedes Layers nach dessen Ausdehnung, sodass ein großflächiger Dienst nicht schon in der Übersicht der Karte angefragt wird.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Gruppe erscheint in der Legende nur für Konten, die das Recht <code>wmssource</code> haben, und das hat keine mitgelieferte Rolle. Fügen Sie es den Gruppen hinzu, die den Dienst sehen sollen, siehe Abschnitt <a href="./19-rollen-und-rechte.html#_19-6-rechte-die-keine-mitgelieferte-rolle-enthalt">Rechte, die keine mitgelieferte Rolle enthält</a>. Ohne das Recht sieht nur das Superuser-Konto den Dienst.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Auch der eigene QGIS-Server lässt sich als Quelle eintragen, etwa um einen Plan aus einem hinterlegten Projekt in der Karte zu zeigen. Die Karte fragt ihn über die öffentliche Adresse ab und braucht dafür unter „Authentifizierung“ die Zugangsdaten eines Kontos, wie in Abschnitt <a href="#_27-3-authentifizierung-der-dienste">Authentifizierung der Dienste</a> beschrieben.</p></div><h2 id="_27-5-wms-proxy-und-zwischenspeicher" tabindex="-1">27.5 WMS-Proxy und Zwischenspeicher <a class="header-anchor" href="#_27-5-wms-proxy-und-zwischenspeicher" aria-label="Permalink to &quot;27.5 WMS-Proxy und Zwischenspeicher&quot;">​</a></h2><p>Die Karte fragt externe Dienste nicht selbst ab, sondern über Qonnectra. Dieser <strong>WMS-Proxy</strong> hält die Zugangsdaten vom Browser fern und speichert jedes abgerufene Kartenbild 30 Tage zwischen. Ein Bildausschnitt, den schon jemand angesehen hat, lädt deshalb sofort, auch wenn der Dienst langsam ist.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ändert sich der Inhalt des externen Dienstes, zeigt die Karte bis zu 30 Tage lang die alten Bilder. Soll ein neuer Stand sofort sichtbar sein, muss der Betrieb den Zwischenspeicher leeren, siehe Abschnitt <a href="./28-betrieb-der-instanz.html#_28-7-haufige-storungen-und-ihre-behebung">Häufige Störungen und ihre Behebung</a>.</p></div>',38)])])}const S=n(o,[["render",u]]);export{f as __pageData,S as default};
